contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address vader, address usdv, address vault) public payable {
        bool firstInitReverted;
        c.init(vader, usdv, vault); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstInitReverted = true; } else { firstInitReverted = false; }

        address v2 = address(uint160(vader) ^ 1);
        address u2 = address(uint160(usdv) ^ 2);
        address va2 = address(uint160(vault) ^ 3);

        bool secondInitReverted;
        c.init(v2, u2, va2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondInitReverted = true; } else { secondInitReverted = false; }

        assert(firstInitReverted == false && secondInitReverted == true);
    }

    receive() external payable {}
}

