pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(address vader, address usdv, address vault) internal {
        bool firstInitReverted;
        try c.init(vader, usdv, vault) { firstInitReverted = false; } catch { firstInitReverted = true; }
        address v2 = address(uint160(vader) ^ 1);
        address u2 = address(uint160(usdv) ^ 2);
        address va2 = address(uint160(vault) ^ 3);
        bool secondInitReverted;
        try c.init(v2, u2, va2) { secondInitReverted = false; } catch { secondInitReverted = true; }
        assertTrue(firstInitReverted == false && secondInitReverted == true);
    }

